#!/usr/bin/env python3
"""Independent cross-check of satsearch.py for small n: breadth-first search over the Boolean algebra generated by the
base sets and the Cpre outputs so far, on the quotient Q_n. A state is the partition of Q_n's classes into atoms of that
algebra; a step picks any union of atoms Y and refines by Cpre(Y); the goal is reached when W is a union of atoms.
Minimal number of steps = B_1(n). Exact but doubly exponential; feasible for n <= 3 (and depth <= 3 at n = 4).
Usage: bfssearch.py n [maxdepth]"""
import sys, os, time, itertools
import numpy as np
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from quotient import build


def canon(part):
    """Canonical relabelling of a partition array (first occurrence order)."""
    _, inv = np.unique(part, return_inverse=True)
    return inv.ravel()


def atoms_of(part):
    k = part.max() + 1
    return [np.nonzero(part == a)[0] for a in range(k)]


def is_goal(part, W):
    # W constant on each atom
    k = part.max() + 1
    cnt = np.bincount(part, minlength=k); wc = np.bincount(part, weights=W, minlength=k)
    return bool(np.all((wc == 0) | (wc == cnt)))


def search(q, maxdepth):
    S, W = q.S, q.W
    start = canon((S.prio == 2).astype(np.int64))
    if is_goal(start, W):
        return 0
    frontier = {start.tobytes(): start}
    for d in range(1, maxdepth + 1):
        nxt = {}
        t0 = time.time()
        for part in frontier.values():
            atoms = atoms_of(part); k = len(atoms)
            for mask in range(1, 2 ** k - 1):  # Y = union of chosen atoms; skip ∅ and V (Cpre(∅)=∅, Cpre(V)=V)
                Y = np.zeros(S.N, dtype=bool)
                for a in range(k):
                    if (mask >> a) & 1:
                        Y[atoms[a]] = True
                C = S.cpre(Y)
                new = canon(part * 2 + C.astype(np.int64))
                if new.max() == part.max():
                    continue  # no refinement
                key = new.tobytes()
                if key in nxt:
                    continue
                if is_goal(new, W):
                    print(f"  depth {d}: goal reached ({len(frontier)} states expanded) [{time.time()-t0:.1f}s]")
                    return d
                nxt[key] = new
        print(f"  depth {d}: {len(nxt)} distinct partitions, no goal [{time.time()-t0:.1f}s]", flush=True)
        frontier = nxt
        if not frontier:
            break
    return None


if __name__ == "__main__":
    n = int(sys.argv[1]); md = int(sys.argv[2]) if len(sys.argv) > 2 else 6
    q = build(n, verbose=True)
    r = search(q, md)
    print(f"BFS: B_1({n}) = {r}" if r is not None else f"BFS: B_1({n}) > {md}")
